import{_ as a,o as n,c as p,a3 as t}from"./chunks/framework.Dz5Q8p4s.js";const o=JSON.parse('{"title":"PixelWizard: Towards Efficient High-Fidelity Video Generation at Ultra-Large Spatial Resolution","description":"","frontmatter":{"title":"PixelWizard: Towards Efficient High-Fidelity Video Generation at Ultra-Large Spatial Resolution","arxiv":"2605.25801","date":"2026-05-25","authors":"Wenxue Li, Jingjing Ren, Peng Zhang, Tian Ye, Daiguo Zhou, Jian Luan, Lei Zhu","categories":"cs.CV","topics":"加速与蒸馏, 高分辨率视频生成, 少步推理","outline":[2,2]},"headers":[],"relativePath":"papers/2605.25801.md","filePath":"papers/2605.25801.md","lastUpdated":null}'),l={name:"papers/2605.25801.md"};function e(i,s,m,r,c,h){return n(),p("div",null,[...s[0]||(s[0]=[t('<h1 id="pixelwizard-towards-efficient-high-fidelity-video-generation-at-ultra-large-spatial-resolution" tabindex="-1">PixelWizard: Towards Efficient High-Fidelity Video Generation at Ultra-Large Spatial Resolution <a class="header-anchor" href="#pixelwizard-towards-efficient-high-fidelity-video-generation-at-ultra-large-spatial-resolution" aria-label="Permalink to &quot;PixelWizard: Towards Efficient High-Fidelity Video Generation at Ultra-Large Spatial Resolution&quot;">​</a></h1><table tabindex="0"><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td><strong>arXiv</strong></td><td><a href="https://arxiv.org/abs/2605.25801" target="_blank" rel="noreferrer">2605.25801</a></td></tr><tr><td><strong>提交日期</strong></td><td>2026-05-25</td></tr><tr><td><strong>作者</strong></td><td>Wenxue Li, Jingjing Ren, Peng Zhang, Tian Ye, Daiguo Zhou, Jian Luan, Lei Zhu</td></tr><tr><td><strong>分类</strong></td><td>cs.CV</td></tr><tr><td><strong>一句话</strong></td><td>先在 448×256 的紧凑 latent 里把全局结构定死当 anchor，再让 2K/4K 的 DiT 只管纹理，并用带噪声跨度对齐的 shortcut 训练把采样压到 4 步，绕开 distillation 的显存墙。</td></tr></tbody></table><blockquote><p><strong>所属教程</strong>：<a href="/notes/tutorials/acceleration-distillation">加速与蒸馏</a></p></blockquote><h2 id="§-1-—-研究问题与重要性" tabindex="-1">§ 1 — 研究问题与重要性 <a class="header-anchor" href="#§-1-—-研究问题与重要性" aria-label="Permalink to &quot;§ 1 — 研究问题与重要性&quot;">​</a></h2><p>直接在 2K（2560×1440）或 4K（3840×2144）网格上跑视频扩散，会同时撞上两堵墙。第一堵是优化：token 数随分辨率平方增长，但一段视频的高层语义总量并不跟着涨，于是每个 token 承载的语义被稀释，梯度被局部纹理主导，模型学不动全局时空结构，表现为物体形变、重复图案、布局崩塌。第二堵是算力：论文实测 Wan2.2-TI2V-5B 直接外推到 4K，一段 121 帧视频要 7150 秒；UltraWan-4K 更是要 24125 秒，也就是接近 7 小时生成一条 5 秒片段。常规的解法——用 distillation 压采样步数——在这个尺度上又要同时把 teacher 和 student 塞进显存，论文称之为 memory wall，Table 8.2 里 FlashVideo（适配 4K）与 UltraWan-4K 都直接 OOM。</p><p>这个问题重要，是因为超高分辨率是内容生产真正的交付格式，而现有三条路线（训练无关的注意力操纵、直接高分训练、后置超分）各有硬伤，没有一条能在质量与延迟上同时站住。</p><h2 id="§-2-—-前人工作与不足" tabindex="-1">§ 2 — 前人工作与不足 <a class="header-anchor" href="#§-2-—-前人工作与不足" aria-label="Permalink to &quot;§ 2 — 前人工作与不足&quot;">​</a></h2><p>论文把先前工作分成三类并逐一点名不足。训练无关方法（FreeScale、CineScale、ScaleCrafter 等）不需要调参，但依赖 patch 级或迭代式细化，既有物体重复与结构畸变，延迟也不低——表 1 里 CineScale-Pro 在 2880×1632 上要 15235 秒。直接高分训练（UltraVideo/UltraWan、UltraGen、URAE）受制于 token 爆炸与语义密度下降，收敛慢、数据贵；表 1 里 UltraWan-4k 的一致性指标最高（Subject 98.64、Motion Smooth 99.56），但 Dynamic Degree 只有 10.00，几乎是静止画面在刷一致性。后置超分（STAR、SeedVR2、DOVE、FlashVSR）受低分输入锚定，无法引入原本不存在的高频语义，表 3 里 STAR 在 3584×2048 上 MUSIQ 只有 20.98、NIQE 7.42，退化明显。</p><p>这些不足有一个共同结构：都试图在同一个高分辨率阶段里同时解决&quot;结构&quot;与&quot;纹理&quot;两件事，或者干脆放弃其中一件。PixelWizard 的立论就是这两件事应当被显式拆开。</p><h2 id="§-3-—-重建作者的思考路径" tabindex="-1">§ 3 — 重建作者的思考路径 <a class="header-anchor" href="#§-3-—-重建作者的思考路径" aria-label="Permalink to &quot;§ 3 — 重建作者的思考路径&quot;">​</a></h2><p>在这篇论文之前，已知的事实有：（1）视频 DiT 的注意力在超长序列下会退化为局部聚合——softmax 在 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal">L</span></span></span></span> 极大时要么过平要么过尖，大量低层 token 的点积相似度彼此接近，全局依赖被稀释；（2）级联式生成（先低分后高分）在图像领域早已被证明有效；（3）shortcut model 通过自一致性学会大步长积分，不需要 teacher，天然省显存；（4）高分辨率生成必须用 shifted noise schedule，时间与噪声的映射是非线性的。</p><p>把这四条串起来的路径是：既然全局结构在低分辨率上更好学（语义密度高），就把它单独拿出来做一个 anchor 阶段；一旦结构被固定，高分阶段面对的概率流就只剩局部纹理合成，轨迹曲率变小，大步长积分才可能成立；而大步长积分的实现要用 shortcut 而不是 distillation，因为后者扛不住 4K 激活的显存；最后，shortcut 的原始设计假设线性 schedule，直接搬到 shifted schedule 上会采样失衡，必须重新设计步长采样与损失加权。这条链条里每一环都由前一环解锁，不需要引用论文自身的贡献做前提。</p><h2 id="§-4-—-核心-intuition" tabindex="-1">§ 4 — 核心 Intuition <a class="header-anchor" href="#§-4-—-核心-intuition" aria-label="Permalink to &quot;§ 4 — 核心 Intuition&quot;">​</a></h2><p>高分辨率视频难生成，不是因为模型不够大，而是因为&quot;全局结构&quot;和&quot;高频纹理&quot;在同一个 token 网格上争夺同一份梯度，而这个网格对前者太稀疏、对后者刚好。把结构挪到一个 14×8 空间 token 的紧凑网格上单独解决，高分阶段就只剩一个局部问题；局部问题的 ODE 轨迹更接近直线，于是四步就能积完。</p><h2 id="§-5-—-具体方法与完整-pipeline" tabindex="-1">§ 5 — 具体方法与完整 Pipeline <a class="header-anchor" href="#§-5-—-具体方法与完整-pipeline" aria-label="Permalink to &quot;§ 5 — 具体方法与完整 Pipeline&quot;">​</a></h2><p>以文中给出的提示&quot;一只戴金叶纹饰的橘猫立于青铜基座，翡翠色眼睛扫视房间&quot;为例：</p><ul><li><strong>Stage I：Spatial-Temporal Anchor Modeling。</strong> 在 448×256 上生成 anchor 视频。这里有个反直觉的坑：直接拿高分先验的模型去低分推理会 representation collapse（布局扭曲、运动不稳），因为每个 token 被迫编码过多空间变化。作者用 6.5 万条低分样本做轻量 tuning 就把生成质量拉回来。VAE 空间压缩 16×、patch embedding 2×，一帧只剩 14×8 = 112 个空间 token。</li><li><strong>Stage II：Anchor-Guided High-Resolution Synthesis。</strong> anchor 被上采样，经一个两层卷积（1×1 后接 3×3）的 Feature Refinement 得到 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1.0272em;vertical-align:-0.2753em;"></span><span class="mord"><span class="mord mathbf">z</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.7519em;"><span style="top:-2.4247em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">A</span></span></span><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">′</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2753em;"><span></span></span></span></span></span></span></span></span></span>，再由 Anchor-Guided Injector 注入 DiT 各 block。注入是带门控的：<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal" style="margin-right:0.0037em;">α</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mop">tanh</span><span class="mopen">(</span><span class="mord text"><span class="mord">MLP</span></span><span class="mopen">(</span><span class="mord text"><span class="mord">SinEmb</span></span><span class="mopen">(</span><span class="mord mathcal" style="margin-right:0.2542em;">T</span><span class="mclose">)</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord text"><span class="mord">SinEmb</span></span><span class="mopen">(</span><span class="mord">Δ</span><span class="mord mathcal" style="margin-right:0.2542em;">T</span><span class="mclose">)))</span></span></span></span>，<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5944em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathbf">z</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">out</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6667em;vertical-align:-0.0833em;"></span><span class="mord mathbf">z</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">(</span><span class="mord">1</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal" style="margin-right:0.0037em;">α</span><span class="mclose">)</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">⋅</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1.0272em;vertical-align:-0.2753em;"></span><span class="mord"><span class="mord mathbf">z</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.7519em;"><span style="top:-2.4247em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">A</span></span></span><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">′</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2753em;"><span></span></span></span></span></span></span></span></span></span>。训练时 anchor 不是 Stage I 的真实输出，而是把真值视频过一遍退化管线（高斯模糊 + 缩放 + 加噪）得到的，逼模型去 hallucinate 纹理而非平凡重建。DiT 主干与 injector 联合训练（消融显示冻结 DiT 只训 adapter 会出块状伪影）。</li><li><strong>Stage III：Noise-Span Aligned Shortcut Training。</strong> 在 Stage II 之上学大步长。</li><li><strong>推理。</strong> 文本 → anchor 视频 → 4 步高分采样 → 2K/4K 输出。表 1 报 PixelWizard-2k 端到端 146 秒、4k 590 秒。</li></ul><h2 id="§-6-—-核心数学推导" tabindex="-1">§ 6 — 核心数学推导 <a class="header-anchor" href="#§-6-—-核心数学推导" aria-label="Permalink to &quot;§ 6 — 核心数学推导&quot;">​</a></h2><p>Shortcut 的基本设定是把速度网络额外条件在步长上，<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6389em;vertical-align:-0.2083em;"></span><span class="mord"><span class="mord mathnormal">x</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3283em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">t</span><span class="mbin mtight">+</span><span class="mord mtight">Δ</span><span class="mord mathnormal mtight">t</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2083em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.7333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal">x</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord">Δ</span><span class="mord mathnormal">t</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">⋅</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord"><span class="mord mathnormal">s</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0278em;">θ</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mopen">(</span><span class="mord"><span class="mord mathnormal">x</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal">t</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">Δ</span><span class="mord mathnormal">t</span><span class="mclose">)</span></span></span></span>，并用自一致性约束训练：一个 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord">2Δ</span><span class="mord mathnormal">t</span></span></span></span> 的大步应当等于两个 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord">Δ</span><span class="mord mathnormal">t</span></span></span></span> 小步的平均速度，</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathcal">L</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">sc</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1.2em;vertical-align:-0.35em;"></span><span class="mord"><span class="mord mathbb">E</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3283em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">t</span><span class="mpunct mtight">,</span><span class="mord mtight">Δ</span><span class="mord mathnormal mtight">t</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span><span class="mord"><span class="delimsizing size1">[</span></span><span class="mord">∥</span><span class="mord"><span class="mord mathnormal">s</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0278em;">θ</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mopen">(</span><span class="mord"><span class="mord mathnormal">x</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal">t</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">2Δ</span><span class="mord mathnormal">t</span><span class="mclose">)</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1.1901em;vertical-align:-0.345em;"></span><span class="mord text"><span class="mord">SG</span></span><span class="mopen">[</span><span class="mord"><span class="mopen nulldelimiter"></span><span class="mfrac"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.8451em;"><span style="top:-2.655em;"><span class="pstrut" style="height:3em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">2</span></span></span></span><span style="top:-3.23em;"><span class="pstrut" style="height:3em;"></span><span class="frac-line" style="border-bottom-width:0.04em;"></span></span><span style="top:-3.394em;"><span class="pstrut" style="height:3em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">1</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.345em;"><span></span></span></span></span></span><span class="mclose nulldelimiter"></span></span><span class="mopen">(</span><span class="mord"><span class="mord mathnormal">s</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0278em;">θ</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mopen">(</span><span class="mord"><span class="mord mathnormal">x</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal">t</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">Δ</span><span class="mord mathnormal">t</span><span class="mclose">)</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord"><span class="mord mathnormal">s</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0278em;">θ</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mopen">(</span><span class="mord"><span class="mord mathnormal">x</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3283em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">t</span><span class="mbin mtight">+</span><span class="mord mtight">Δ</span><span class="mord mathnormal mtight">t</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2083em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal">t</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1.2141em;vertical-align:-0.35em;"></span><span class="mord">Δ</span><span class="mord mathnormal">t</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">Δ</span><span class="mord mathnormal">t</span><span class="mclose">))]</span><span class="mord"><span class="mord">∥</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.8641em;"><span style="top:-2.453em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">2</span></span></span><span style="top:-3.113em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">2</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.247em;"><span></span></span></span></span></span></span><span class="mord"><span class="delimsizing size1">]</span></span><span class="mord">.</span></span></span></span></span></p><p>停止梯度 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord text"><span class="mord">SG</span></span><span class="mopen">[</span><span class="mord">⋅</span><span class="mclose">]</span></span></span></span> 防止塌到平凡解。直觉是：小步是可靠的（因为 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord">Δ</span><span class="mord mathnormal">t</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">→</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">0</span></span></span></span> 时退化为标准 flow matching），大步的监督信号由小步自举出来，不需要 teacher。</p><p>本文的两处改动都针对 shifted schedule。第一，把时间轴离散成 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.109em;">N</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">1000</span></span></span></span> 个索引，先限定在高噪区间 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7224em;vertical-align:-0.0391em;"></span><span class="mord mathcal" style="margin-right:0.2542em;">T</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">∈</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">{</span><span class="mord">500</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">600</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">700</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">800</span><span class="mclose">}</span></span></span></span>，候选步长取二分序列 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord">Δ</span><span class="mord"><span class="mord mathcal" style="margin-right:0.2542em;">T</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.2542em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0315em;">k</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mopen">(</span><span class="mord mathcal" style="margin-right:0.2542em;">T</span><span class="mclose">)</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1.0991em;vertical-align:-0.25em;"></span><span class="mopen">⌊</span><span class="mord mathcal" style="margin-right:0.2542em;">T</span><span class="mord">/</span><span class="mord"><span class="mord">2</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8491em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0315em;">k</span></span></span></span></span></span></span></span><span class="mclose">⌋</span></span></span></span>（<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6944em;"></span><span class="mord mathnormal" style="margin-right:0.0315em;">k</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.8389em;vertical-align:-0.1944em;"></span><span class="mord">0</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="minner">…</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">5</span></span></span></span>），再对索引 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6944em;"></span><span class="mord mathnormal" style="margin-right:0.0315em;">k</span></span></span></span> 做指数偏置采样</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal">p</span><span class="mopen">(</span><span class="mord mathnormal" style="margin-right:0.0315em;">k</span><span class="mclose">)</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:2.734em;vertical-align:-1.307em;"></span><span class="mord"><span class="mopen nulldelimiter"></span><span class="mfrac"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:1.427em;"><span style="top:-2.1288em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mop"><span class="mop op-symbol small-op" style="position:relative;top:0em;">∑</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.9812em;"><span style="top:-2.4003em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight" style="margin-right:0.0572em;">j</span><span class="mrel mtight">=</span><span class="mord mtight">0</span></span></span></span><span style="top:-3.2029em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight" style="margin-right:0.0715em;">K</span><span class="mbin mtight">−</span><span class="mord mtight">1</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.4358em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mop">exp</span><span class="mopen">(</span><span class="mord">−</span><span class="mord mathnormal" style="margin-right:0.0528em;">β</span><span class="mord mathnormal" style="margin-right:0.0572em;">j</span><span class="mclose">)</span></span></span><span style="top:-3.23em;"><span class="pstrut" style="height:3em;"></span><span class="frac-line" style="border-bottom-width:0.04em;"></span></span><span style="top:-3.677em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mop">exp</span><span class="mopen">(</span><span class="mord">−</span><span class="mord mathnormal" style="margin-right:0.0528em;">β</span><span class="mord mathnormal" style="margin-right:0.0315em;">k</span><span class="mclose">)</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:1.307em;"><span></span></span></span></span></span><span class="mclose nulldelimiter"></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:1em;"></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.0528em;">β</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.8389em;vertical-align:-0.1944em;"></span><span class="mord">0.7</span><span class="mpunct">,</span></span></span></span></span></p><p>使 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6944em;"></span><span class="mord mathnormal" style="margin-right:0.0315em;">k</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">→</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">0</span></span></span></span>（最大步长）被高频采样。原始 shortcut 在候选集上均匀采样，在非线性时间-噪声映射下会大量抽到&quot;物理噪声变化可以忽略&quot;的步，导致大步长欠训练。</p><p>第二，损失加权不按 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathcal" style="margin-right:0.2542em;">T</span></span></span></span> 也不按 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord">Δ</span><span class="mord mathcal" style="margin-right:0.2542em;">T</span></span></span></span>，而按这一段轨迹真正跨越的噪声量</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.9694em;vertical-align:-0.2861em;"></span><span class="mord">Δ</span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">σ</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3283em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathcal mtight" style="margin-right:0.2542em;">T</span><span class="mpunct mtight">,</span><span class="mord mtight">Δ</span><span class="mord mathcal mtight" style="margin-right:0.2542em;">T</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1.1052em;vertical-align:-0.3552em;"></span><span class="mord">∣</span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">σ</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3448em;"><span style="top:-2.5198em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">t</span><span class="mopen mtight">(</span><span class="mord mathcal mtight" style="margin-right:0.2542em;">T</span><span class="mbin mtight">+</span><span class="mord mtight">Δ</span><span class="mord mathcal mtight" style="margin-right:0.2542em;">T</span><span class="mclose mtight">)</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.3552em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1.1052em;vertical-align:-0.3552em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">σ</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3448em;"><span style="top:-2.5198em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">t</span><span class="mopen mtight">(</span><span class="mord mathcal mtight" style="margin-right:0.2542em;">T</span><span class="mclose mtight">)</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.3552em;"><span></span></span></span></span></span></span><span class="mord">∣</span><span class="mpunct">,</span><span class="mspace" style="margin-right:2em;"></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal">λ</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">(</span><span class="mord">Δ</span><span class="mord mathnormal" style="margin-right:0.0359em;">σ</span><span class="mclose"><span class="mclose">)</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.7144em;"><span style="top:-3.113em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">p</span></span></span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace"> </span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal">p</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.8389em;vertical-align:-0.1944em;"></span><span class="mord">0.5</span><span class="mpunct">,</span></span></span></span></span></p><p>最终目标 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathcal">L</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3283em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">ANC</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6944em;"></span><span class="mord mathnormal">λ</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">⋅</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathcal">L</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">sc</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span>，与 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathcal">L</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">flow</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 在 mini-batch 间交替更新。这一项的 intuition 是：预测一次转移的难度由这段轨迹跨过多少噪声决定，而不是由起点时刻或名义步数决定。</p><h2 id="§-7-—-实验设计与结论" tabindex="-1">§ 7 — 实验设计与结论 <a class="header-anchor" href="#§-7-—-实验设计与结论" aria-label="Permalink to &quot;§ 7 — 实验设计与结论&quot;">​</a></h2><p><strong>结构解耦真的解决了优化问题吗？</strong> 作者在同等数据预算下与&quot;直接高分微调&quot;对比（图 5），后者出现主体重复、空间错位、布局不稳。表 4 的组件消融：只有 anchor 时 Tech 8.01，未 tuning 的 anchor 崩到 3.30，加 AGHS 但用逐元素相加注入是 12.51，加门控但 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal" style="margin-right:0.0037em;">α</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">0</span></span></span></span> 是 13.47，完整版 14.31。可以看出结构解耦本身贡献最大（8.01→12.51），自适应门控只值 0.84。</p><p><strong>shortcut 的两处改动各值多少？</strong> 表 9.3（4 步推理）：baseline MUSIQ 51.54，原始均匀采样 shortcut 53.08，加指数偏置采样 56.43，再加噪声跨度校准 57.67。指数偏置采样是主力（+3.35），校准再补 +1.24。</p><p><strong>质量与效率。</strong> 表 1 用 VBench 100 条提示的 6 个维度，PixelWizard-2k 平均 79.34、4k 79.62，都是全表最高；相对 Wan2.2 直接外推的加速是 1635/146≈11.2×（2K）与 7150/590≈12.1×（4K），与摘要的&quot;超过 10×&quot;吻合。表 2/3 用 mHD-MSE、mHD-LPIPS（越高表示细节越丰富）与 DOVER，PixelWizard 全面领先超分方法。</p><p>需要如实指出几处：（a）表 1 的 79.34 只比 CineScale-Pro 的 79.25 高 0.09，而 PixelWizard 的 Dynamic Degree 49.00 低于 CineScale-Pro 的 56.00，Subject Consistency 96.16 也低于 UltraWan-1k 的 96.51，平均分领先主要由 Imaging Quality（72.64/74.25）拉动。（b）表 8.1 的 VBench-Long 上 PixelWizard-2k 总分 83.62 第一，但 Quality Score 84.56 低于 Wan2.1-T2V-1.3B 的 85.23 与 HunyuanVideo 的 85.09，Dynamic Degree 55.55 明显低于 Turbo2K 的 74.65，Color 76.82 也低于同表多数方法；总分优势来自 Object Class 96.01 与 Multiple Objects 86.16。（c）正文说&quot;采用 4 步&quot;，但表 5 里 3 步是 14.31/99.56、4 步是 14.39/99.58，而表 9.3 标注为 4 步的完整模型是 14.31/99.58——主表数值与表 5 的 4 步行对不上，与 3 步行的 Tech 反而一致。（d）表 5 的延迟 2→3→4 步各增 33 秒，4→5 步却跳 99 秒，未解释；且表 1 报的端到端 146 秒小于表 5 中 stage-II 单独 4 步的 165 秒，两处口径不一致。（e）各基线在各自&quot;官方支持配置&quot;下评测（附录 8.2 明说），分辨率、帧数、fps 都不同，延迟横比只能当量级参考。</p><h2 id="§-8-—-take-aways" tabindex="-1">§ 8 — Take-aways <a class="header-anchor" href="#§-8-—-take-aways" aria-label="Permalink to &quot;§ 8 — Take-aways&quot;">​</a></h2><p><strong>5 句话版。</strong> 高分辨率视频生成的核心矛盾是语义密度稀释导致全局结构与局部纹理争夺梯度。PixelWizard 把结构生成挪到 448×256（每帧仅 112 个空间 token）的 anchor 阶段，再用带时间步门控的 injector 把 anchor 注入高分 DiT。结构被固定后概率流更局部，为大步长积分创造条件。作者用 shortcut 而非 distillation 实现少步推理，避开 4K 激活下的 teacher-student 显存墙，并用指数偏置步长采样与噪声跨度加权修正 shifted schedule 带来的采样失衡。结果是 2K/4K 上相对基座 10 倍以上的采样加速，代价是 Dynamic Degree 系统性偏低。</p><p><strong>3 句话版。</strong> 先低分定结构、再高分补纹理，把一个病态优化问题拆成两个良态问题。结构固定后 ODE 轨迹更直，4 步 shortcut 就够用，且不需要 teacher。速度赢了一个数量级，质量指标的领先幅度则要打折看。</p><p><strong>1 句话版。</strong> 用一个 112 token 的低分 anchor 换取 4K 阶段的优化稳定性与四步可积性。</p><h2 id="§-9-—-最脆弱的假设" tabindex="-1">§ 9 — 最脆弱的假设 <a class="header-anchor" href="#§-9-—-最脆弱的假设" aria-label="Permalink to &quot;§ 9 — 最脆弱的假设&quot;">​</a></h2><p>最致命的一条是：<strong>训练时用&quot;退化真值&quot;当 anchor，推理时用&quot;Stage I 生成结果&quot;当 anchor，两者的分布被默认足够接近。</strong> 训练侧的 anchor 由高斯模糊、缩放、加噪构造，其误差是各向同性、无结构的低通失真；而 Stage I 生成的 anchor 的误差是结构性的——错误的物体数量、错误的运动方向、错误的布局拓扑。如果 Stage II 只学会了&quot;从模糊图恢复高频&quot;，它就没有任何机制去纠正一个结构上就错了的 anchor。</p><p>若这条不成立，整个 divide-and-conquer 的收益直接归零：Stage I 的结构错误会被 Stage II 忠实放大到 4K。论文提供的证据是附录 §9.4：给出若干 Stage I anchor 明显有缺陷的定性例子，显示 Stage II 能补回断裂结构、从模糊 anchor 恢复语义细节。但这只是定性图，没有任何&quot;anchor 质量 → 最终质量&quot;的定量曲线，也没有在受控扰动（比如人为改变 anchor 里的物体数量）下测量恢复率。所缺的正是最关键的证据。</p><h2 id="§-10-—-最小复现实验" tabindex="-1">§ 10 — 最小复现实验 <a class="header-anchor" href="#§-10-—-最小复现实验" aria-label="Permalink to &quot;§ 10 — 最小复现实验&quot;">​</a></h2><p>不需要复现 2K/4K 系统。用 Wan2.2-TI2V-5B 或任何开源 DiT，在 512×288 上：</p><ol><li>用 65k 量级低分样本（或公开子集）微调出一个 128×72 的 anchor 模型，验证&quot;直接低分推理会 collapse、微调后恢复&quot;这一现象是否可复现（这是 Stage I 的全部前提）。</li><li>训练一个只带 Anchor-Guided Injector 的 512×288 学生，anchor 用退化真值构造。</li><li><strong>关键测量</strong>：在测试时分别喂三种 anchor——退化真值、Stage I 生成、以及人为结构扰动过的 anchor（例如把主体平移 30% 画幅或复制成两个）。记录三种条件下的 mHD-LPIPS 与主体计数正确率。</li><li>判据：若&quot;Stage I 生成&quot;这一档与&quot;退化真值&quot;档的差距小于扰动档的一半，支持论文的鲁棒性主张；若三档单调劣化且生成档已接近扰动档，则说明退化管线不是生成误差的合格代理。</li></ol><p>一周内可完成，因为不涉及 shortcut 训练，也不涉及 4K 显存。</p><h2 id="§-11-—-最强反例设计" tabindex="-1">§ 11 — 最强反例设计 <a class="header-anchor" href="#§-11-—-最强反例设计" aria-label="Permalink to &quot;§ 11 — 最强反例设计&quot;">​</a></h2><p>针对指标的攻击最有力。mHD-MSE 与 mHD-LPIPS 的定义是&quot;把视频降采样 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8491em;"></span><span class="mord"><span class="mord">2</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8491em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0315em;">k</span></span></span></span></span></span></span></span></span></span></span> 倍再升回来，测重建差异&quot;，作者明确说明<strong>数值越高表示细节越丰富</strong>。这个量在数学上就是高频能量的一种度量，它无法区分&quot;语义上正确的纹理&quot;和&quot;任何高频扰动&quot;。构造一个反例：取 UltraWan-4k 的输出，叠加一层幅度极小的高频噪声或做一次非锐化掩模（unsharp mask），mHD-MSE 与 mHD-LPIPS 都会单调上升，而语义质量不变甚至变差。如果这样一个零成本后处理就能把基线的 mHD 指标推到 PixelWizard 水平，那么表 2/表 3 里的领先就不构成&quot;细节更真实&quot;的证据。论文没有做这个负控制。</p><p>第二条攻击给出替代解释：PixelWizard 在表 1 与表 8.1 上 Dynamic Degree 都明显偏低（49.00 vs CineScale-Pro 56.00；55.55 vs Turbo2K 74.65），而 Subject/Background Consistency 与 Motion Smoothness 都偏高。VBench 的平均分是各维等权算术平均，压制运动会同时抬高三项一致性指标、只损失一项 Dynamic Degree，净收益为正。因此&quot;平均分最高&quot;至少部分可以用&quot;anchor 把运动锁死了&quot;来解释——anchor 只有 14×8 个空间 token，能表达的运动本身就是粗粒度的，Stage II 又被要求与之保持结构一致。论文的 Limitations 一节也承认复杂或快速运动仍会出现局部形变与轨迹不一致，与这个解释方向一致。</p><h2 id="§-12-—-follow-up-research-idea" tabindex="-1">§ 12 — Follow-up Research Idea <a class="header-anchor" href="#§-12-—-follow-up-research-idea" aria-label="Permalink to &quot;§ 12 — Follow-up Research Idea&quot;">​</a></h2><p><strong>(a) 驱动局限。</strong> 本文的 anchor 是一个固定分辨率、一次性生成、之后只读的结构先验；Stage II 无法把自己发现的矛盾反馈回去，Stage I 也无从知道哪些结构决策是&quot;高风险&quot;的。§9 指出的分布错配、§11 指出的运动压制，根子都在这个单向接口上。</p><p><strong>(b) 可借鉴的相邻领域。</strong> 视频编解码里的率失真优化（RDO）与可伸缩编码（SVC）处理的正是同一个问题：如何在多个尺度间分配比特，并让解码端知道每个尺度的置信度。把 anchor 视作&quot;基本层&quot;、高分残差视作&quot;增强层&quot;，就可以引入一个显式的<strong>结构置信图</strong>：anchor 每个 token 附带一个不确定度，Stage II 在高置信区域严格遵从、在低置信区域允许重新采样甚至改写布局。相关的技术工具是 diffusion 的 inpainting/重绘掩码与 classifier-free guidance 的空间调制。</p><p><strong>(c) 第一个实验。</strong> 不改架构，只改训练：在 Stage I 上做 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.109em;">M</span></span></span></span> 次采样，用像素级方差得到一张置信图，把它作为第 4 个通道喂给 Anchor-Guided Injector，并把式 (2) 的标量增益 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal" style="margin-right:0.0037em;">α</span></span></span></span> 改成逐位置的 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal" style="margin-right:0.0037em;">α</span><span class="mopen">(</span><span class="mord mathnormal">u</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;">v</span><span class="mclose">)</span></span></span></span>。评测两件事：（1）在人为扰动 anchor 的条件下（§10 的第三档），带置信图的模型是否显著提高主体计数正确率；（2）Dynamic Degree 是否回升——如果低置信区域被允许重新生成运动，压制效应应当减弱。这个实验能同时检验 §9 的脆弱假设与 §11 的替代解释，且成本只比原方法多一次 Stage I 采样。</p>',50)])])}const d=a(l,[["render",e]]);export{o as __pageData,d as default};
